import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long p = nextLong();
        long[] a = new long[n];
        long sum = 0, biggest = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            sum += a[i];
            biggest = Math.max(biggest, a[i]);
        }
        // Lower bound for any plan: the current maximum and the rounded-up average.
        long cap = Math.max(biggest, (sum + p + n - 1) / n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long put = Math.min(p, cap - a[i]);
            a[i] += put;
            p -= put;
            sb.append(a[i]).append(i + 1 < n ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n, p := readInt(), readInt()
	a := make([]int, n)
	sum, biggest := 0, 0
	for i := range a {
		a[i] = readInt()
		sum += a[i]
		biggest = max(biggest, a[i])
	}
	// Lower bound for any plan: the current maximum and the rounded-up average.
	capacity := max(biggest, (sum+p+n-1)/n)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := range a {
		put := min(p, capacity-a[i])
		a[i] += put
		p -= put
		w.WriteString(strconv.Itoa(a[i]))
		if i+1 < n {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
